INSERT INTO foeto_terms VALUES('FOETO:0170204b','multi_organe','Surcharge macrophagique en mucopolysaccharides et lipides','Macrophage storage of mucopolysaccharides and lipids','macrophage_storage_mucopolysaccharides_lipids','pathologie','region','','saudubray_ch32_cholesterol_slo',1,'OMIM:230650|OMIM:245900|OMIM:257220|OMIM:269600|OMIM:301000|OMIM:604809|OMIM:607625|OMIM:619802|OMIM:620937','ORPHA:139|ORPHA:264675|ORPHA:646|ORPHA:747','APOE|CSF2RA|CSF2RB|GLB1|HLA-DRB1|LCAT|NPC1|NPC2|NSDHL|PIK3CG|RBSN|WAS','cerveau|foie|hematolymphoide|squelette','Accumulation intracytoplasmique dans les macrophages de matériel de surcharge mixte comprenant des mucopolysaccharides (PAS+, bleu alcian+) et des lipides (Oil Red O+, si tissu frais), observée dans tous les systèmes d''organes. Les cellules parenchymateuses peuvent être secondairement atteintes à un',NULL,NULL,NULL,0);
INSERT INTO foeto_terms VALUES('FOETO:0170205b','multi_organe','Accumulation intracellulaire de cholestérol non estérifié','Unesterified intracellular cholesterol accumulation','unesterified_intracellular_cholesterol_accumulation','pathologie','region','','saudubray_ch32_cholesterol_slo',1,'OMIM:136120|OMIM:143890|OMIM:144010|OMIM:144250|OMIM:144300|OMIM:151660|OMIM:230650|OMIM:245900|OMIM:257220|OMIM:267700','ORPHA:139|ORPHA:209902|ORPHA:247598|ORPHA:261|ORPHA:264675|ORPHA:330015|ORPHA:391665|ORPHA:412|ORPHA:470|ORPHA:646','ABCA2|ABCG5|ABCG8|ALB|APOA2|APOB|APOE|CELA2A|CEP19|CSF2RA|CSF2RB|CYP7A1|DYRK1B|EMD|EPHX2|FHL1|GHR|GLB1|HLA-DRB1|LCAT','cerveau|foie|hematolymphoide','Accumulation anormale de cholestérol non estérifié dans le compartiment intracellulaire (lysosomes), démontrable par la coloration filipine (fluorescence spécifique du cholestérol libre) sur coupes à congélation. Analogue au profil observé dans la maladie de Niemann-Pick C. Dans le syndrome de Smith',NULL,NULL,NULL,0);
