INSERT INTO foeto_terms VALUES('FOETO:0170216b','multi_organe','Anomalie nucléaire des granulocytes (hypolobulation)','Granulocyte nuclear hypolobulation','granulocyte_nuclear_hypolobulation','pathologie','region','FOETO:0170217','saudubray_ch32_cholesterol_slo',0,'OMIM:127550|OMIM:152700|OMIM:214500|OMIM:216550|OMIM:222700|OMIM:229050|OMIM:231095|OMIM:242840|OMIM:243500|OMIM:251000','ORPHA:108|ORPHA:124|ORPHA:1304|ORPHA:1328|ORPHA:137698|ORPHA:20|ORPHA:206572|ORPHA:227982|ORPHA:227990|ORPHA:2298','ADA2|ADH5|AK2|ARHGAP31|ATP6AP1|BANK1|BCOR|BLK|BLOC1S6|BRAF|BRCA1|BRCA2|BRIP1|BTNL2|C1GALT1C1|C4A|C4B|CA2|CLPB|COPZ1','hematolymphoide','Anomalie morphologique nucléaire des granulocytes caractérisée en microscopie sur frottis sanguin ou médullaire par des noyaux bilobés en forme de cacahuète ou pince-nez (aspect hypolobé) avec une structure chromatinienne anormale (hétérochromatine condensée). Signe de l''anomalie de Pelger-Huët, alliant hypolobulation et structure chromatinienne perturbée. Associé aux mutations LBR.',NULL,NULL,NULL,0);
