PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE foeto_terms (
    id                TEXT PRIMARY KEY,
    organe            TEXT NOT NULL,
    label_fr          TEXT,
    label_en          TEXT,
    code              TEXT,
    axis              TEXT,
    annotation_type   TEXT,
    merged_from       TEXT,
    sources           TEXT,
    hpo_inferred_count INTEGER DEFAULT 0,
    omim              TEXT,
    orpha             TEXT,
    genes             TEXT,
    multisysteme      TEXT,
    description_fr    TEXT
, viewer_level INTEGER, viewer_id TEXT, viewer_color TEXT, viewer_quick INTEGER DEFAULT 0);
COMMIT;
